"use strict";(self.webpackChunk_repo_brand=self.webpackChunk_repo_brand||[]).push([[342],{"./stories/guide/06-screens.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("../../node_modules/next/dist/compiled/react/index.js");var jsx_runtime=__webpack_require__("../../node_modules/next/dist/compiled/react/jsx-runtime.js"),lib=__webpack_require__("../../node_modules/@mdx-js/react/lib/index.js"),blocks=__webpack_require__("../../node_modules/@storybook/addon-docs/dist/blocks.js");function _createMdxContent(props){return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(blocks.W8,{title:"Guide/Screens"}),"\n",(0,jsx_runtime.jsx)(blocks.oz,{children:'# Screens\n\nauibsal.org and the Diwan share one frame. Few boxes, big words, a lot of air. The English site is English only and the Arabic site Arabic only.\n\n- **Header:** one line. The lockup in the page\'s language, five sections at most, the other language, the theme toggle and Sign in as text links. A hairline below.\n- **Front door:** the motto, one sentence, one button. Section titles stand alone, with at most a link at the end of the line.\n- **Events:** a dated list, large Light day numbers down the margin, like an almanac.\n- **Qirtas:** the Society\'s paper, on paper, with a masthead and no empty image spaces.\n- **"Come in."** One ink band with the invitation, then the ink footer: three short columns.\n- **Arabic pages** mirror the layout, with the Arabic lockup and Ubuntu Arabic Regular for display.\n- **Phones:** nothing scrolls sideways at 360 px. Errors say what happened and what to do; no exclamation marks.\n\n## In Arabic, on phones\n\nThe Arabic site is its own edition: the same layout mirrored, the Arabic lockup, Ubuntu Arabic Regular. Phones get the same page in one column.\n\n- **Mirrored:** `dir="rtl"` on the page; the lockup at the top right; links and dates on the start side.\n- Display in Ubuntu Arabic Regular at 1.3 leading; the accent word changes color only.\n- Latin strings (@auibsal, links, emails) are wrapped in `<bdi dir="ltr">` so they read the right way.\n- **Phones:** the lockup at 40 px, a Menu link in place of the sections, the motto at 56–64 px.\n- Lists keep their dates; the time and place move under the title.\n- Nothing scrolls sideways at 360 px. Tap targets are 44 px or larger.\n'})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,lib.R)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent()}}}]);
